262→// ---------------------------------------------------------------------------
263→// Types
264→// ---------------------------------------------------------------------------
265→
266→type ActionData =
267→  | { ok: true; message: string; redirectId?: string }
268→  | { error: string };
269→
270→// ---------------------------------------------------------------------------
271→// Constants
272→// ---------------------------------------------------------------------------
273→
