275→  tops: "Tops",
276→  bottoms: "Bottoms",
277→  dresses: "Dresses",
278→  shoes: "Shoes",
279→  kids: "Kids",
280→  rings: "Rings",
281→  sportswear: "Sportswear",
282→  general: "General",
283→};
284→
285→const CATEGORY_ICONS: Record<string, string> = {
