307→// ---------------------------------------------------------------------------
308→// Helpers
309→// ---------------------------------------------------------------------------
310→
311→function formatDate(date: string | Date): string {
312→  return new Date(date).toLocaleDateString("en-US", {
313→    month: "short",
314→    day: "numeric",
315→    year: "numeric",
316→  });
317→}
