323→interface TemplateSectionProps {
324→  templates: Array<{ name: string; category: string; gender: string; rowCount: number }>;
325→  categories: string[];
326→  isLoading: boolean;
327→  onClose: () => void;
328→  fetcher: ReturnType<typeof useFetcher<typeof action>>;
329→}
