331→function TemplatePicker({ templates, categories, isLoading, fetcher }: TemplateSectionProps) {
332→  const [selectedCategory, setSelectedCategory] = useState<string>("all");
333→
334→  const filteredTemplates = selectedCategory === "all"
335→    ? templates
336→    : templates.filter((t) => t.category === selectedCategory);
337→
338→  return (
339→    <BlockStack gap="400">
340→      {/* Category filter */}
341→      <ButtonGroup variant="segmented">
342→        <Button
343→          variant={selectedCategory === "all" ? "primary" : undefined}
344→          onClick={() => setSelectedCategory("all")}
345→        >
346→          All
347→        </Button>
348→        {categories.map((cat) => (
349→          <Button
350→            key={cat}
351→            variant={selectedCategory === cat ? "primary" : undefined}
352→            onClick={() => setSelectedCategory(cat)}
353→          >
354→            {CATEGORY_ICONS[cat] ?? "📏"} {CATEGORY_LABELS[cat] ?? cat}
355→          </Button>
356→        ))}
357→      </ButtonGroup>
358→
359→      {/* Blank chart */}
360→      <Card>
361→        <InlineStack gap="400" align="space-between" blockAlign="center">
362→          <BlockStack gap="100">
363→            <Text as="p" variant="bodyMd" fontWeight="bold">Blank chart</Text>
364→            <Text as="p" variant="bodyMd" tone="subdued">
365→              Start with an empty table — add your own columns and sizes
366→            </Text>
367→          </BlockStack>
368→          <fetcher.Form method="post">
369→            <input type="hidden" name="intent" value="create-blank" />
370→            <input type="hidden" name="name" value="Untitled Size Chart" />
371→            <input type="hidden" name="category" value="general" />
372→            <Button submit loading={isLoading}>Create blank</Button>
373→          </fetcher.Form>
374→        </InlineStack>
375→      </Card>
376→
377→      {/* Template grid */}
378→      {filteredTemplates.length > 0 ? (
379→        <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
380→          {filteredTemplates.map((template) => (
381→            <Card key={template.name}>
382→              <BlockStack gap="200">
383→                <InlineStack gap="200" blockAlign="center">
384→                  <Text as="span" variant="bodyMd">{CATEGORY_ICONS[template.category] ?? "📏"}</Text>
385→                  <Text as="p" variant="bodyMd" fontWeight="bold">{template.name}</Text>
386→                </InlineStack>
387→                <InlineStack gap="200">
388→                  <Badge tone="info">{CATEGORY_LABELS[template.category] ?? template.category}</Badge>
389→                  <Text as="span" variant="bodyMd" tone="subdued">{template.rowCount} sizes</Text>
390→                </InlineStack>
391→                <fetcher.Form method="post">
392→                  <input type="hidden" name="intent" value="create-from-template" />
393→                  <input type="hidden" name="templateName" value={template.name} />
394→                  <Button variant="primary" submit loading={isLoading}>
395→                    Use template
396→                  </Button>
397→                </fetcher.Form>
398→              </BlockStack>
399→            </Card>
400→          ))}
401→        </InlineGrid>
402→      ) : (
403→        <Text as="p" variant="bodyMd" tone="subdued">No templates in this category.</Text>
404→      )}
405→    </BlockStack>
406→  );
407→}
