 773→type LoaderData = Awaited<ReturnType<typeof loader>>;
 774→type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";
 775→
 776→export default function SizeChartEditor() {
 777→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 778→  const { chart, assignments: initialAssignments, isNew } = loaderData;
 779→  const navigate = useNavigate();
 780→
 781→  const saveFetcher = useFetcher<typeof action>();
