 783→  const assignmentFetcher = useFetcher<typeof action>();
 784→  const shopify = useAppBridge();
 785→
 786→  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
 787→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
 788→  const [category, setCategory] = useState(chart?.category ?? "general");
 789→  const [status, setStatus] = useState(chart?.status ?? "draft");
 790→  const [chartData, setChartData] = useState<ChartData>(
 791→    chart ? parseChartData(chart.data) : makeDefaultData(),
 792→  );
 793→  const [assignments, setAssignments] =
 794→    useState<Assignment[]>(initialAssignments);
 795→  const [newAssignmentType, setNewAssignmentType] = useState("product");
 796→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
 797→
 798→  // Position settings (stored in chartData.displaySettings)
 799→  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
 800→  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
 801→  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
 802→  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
 803→  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
 804→  const [recommendationEnabled, setRecommendationEnabled] = useState(
 805→    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
 806→  );
 807→
 808→  const isSaving = saveFetcher.state !== "idle";
 809→  const isTogglingStatus = statusFetcher.state !== "idle";
 810→
 811→  // Check for ?saved=1 on mount (after redirect from new chart creation)
 812→  useEffect(() => {
 813→    if (typeof window !== "undefined") {
 814→      const url = new URL(window.location.href);
 815→      if (url.searchParams.get("saved") === "1") {
 816→        shopify.toast.show("Chart created successfully");
 817→        url.searchParams.delete("saved");
 818→        window.history.replaceState({}, "", url.toString());
 819→      }
 820→    }
 821→  }, [shopify]);
 822→
 823→  // Save feedback
