 825→    if (!saveFetcher.data) return;
 826→    const data = saveFetcher.data;
 827→    if ("ok" in data && data.ok) {
 828→      shopify.toast.show(data.message ?? "Saved");
 829→    } else if ("error" in data) {
 830→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 831→    }
 832→  }, [saveFetcher.data, shopify]);
 833→
 834→  // Status toggle feedback
 835→  useEffect(() => {
 836→    if (!statusFetcher.data) return;
 837→    const data = statusFetcher.data;
 838→    if ("ok" in data && data.ok) {
 839→      shopify.toast.show(data.message ?? "Status updated");
