 56→// ---------------------------------------------------------------------------
 57→// Loader
 58→// ---------------------------------------------------------------------------
 59→
 60→export const loader = async ({ request }: LoaderFunctionArgs) => {
 61→  const { session } = await authenticate.admin(request);
 62→  const shop = session.shop;
 63→
 64→  const [config, subscription, charts] = await Promise.all([
 65→    db.recommenderConfig.findUnique({ where: { shop } }),
 66→    db.subscription.findUnique({ where: { shop } }),
 67→    db.sizeChart.findMany({
 68→      where: { shop, status: "active" },
 69→      select: { id: true, name: true, category: true },
 70→      orderBy: { name: "asc" },
 71→    }),
 72→  ]);
 73→
 74→  const plan = getPlan(subscription?.planId ?? "free");
 75→  const canUseAi = hasFeature(plan.id, "aiRecommender");
 76→  const canUseAdvanced = hasFeature(plan.id, "advancedAi");
 77→
 78→  let bodyTypes = DEFAULT_BODY_TYPES;
 79→  if (config?.bodyTypes) {
 80→    try {
 81→      const saved = JSON.parse(config.bodyTypes) as Array<{ id: string; enabled: boolean }>;
 82→      bodyTypes = DEFAULT_BODY_TYPES.map((bt) => {
 83→        const match = saved.find((s) => s.id === bt.id);
 84→        return match ? { ...bt, enabled: match.enabled } : bt;
 85→      });
 86→    } catch {
 87→      bodyTypes = DEFAULT_BODY_TYPES;
 88→    }
 89→  }
 90→
 91→  let sizingRules: Record<string, string> = {};
 92→  if (config?.sizingRules) {
 93→    try {
