122→export const action = async ({ request }: ActionFunctionArgs) => {
123→  const { session } = await authenticate.admin(request);
124→  const shop = session.shop;
125→  const formData = await request.formData();
126→  const intent = formData.get("intent") as string;
127→
128→  try {
129→    switch (intent) {
130→      case "toggle": {
131→        const subscription = await db.subscription.findUnique({ where: { shop } });
132→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
133→          return { error: "AI recommender requires Growth plan or higher", intent };
134→        }
135→        const current = await db.recommenderConfig.findUnique({ where: { shop } });
136→        const newEnabled = !current?.enabled;
137→        await db.recommenderConfig.upsert({
138→          where: { shop },
139→          update: { enabled: newEnabled },
140→          create: { shop, enabled: newEnabled },
141→        });
142→        return {
143→          ok: true,
144→          intent,
145→          enabled: newEnabled,
146→          message: newEnabled ? "AI Recommender enabled" : "AI Recommender disabled",
147→        };
148→      }
149→
150→      case "update-settings": {
151→        const subscription = await db.subscription.findUnique({ where: { shop } });
152→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
153→          return { error: "AI recommender requires Growth plan or higher", intent };
154→        }
155→        const algorithm = (formData.get("algorithm") as string) || DEFAULT_ALGORITHM;
156→        await db.recommenderConfig.upsert({
157→          where: { shop },
158→          update: { algorithm },
159→          create: { shop, algorithm },
160→        });
161→        return { ok: true, intent, message: "Algorithm updated" };
162→      }
163→
164→      case "save-body-types": {
165→        const subscription = await db.subscription.findUnique({ where: { shop } });
166→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
167→          return { error: "AI recommender requires Growth plan or higher", intent };
168→        }
169→        const bodyTypesRaw = formData.get("bodyTypes") as string;
170→        if (!bodyTypesRaw) return { error: "No body types data", intent };
171→        await db.recommenderConfig.upsert({
172→          where: { shop },
173→          update: { bodyTypes: bodyTypesRaw },
174→          create: { shop, bodyTypes: bodyTypesRaw },
175→        });
176→        return { ok: true, intent, message: "Body types saved" };
177→      }
178→
179→      case "save-sizing-rules": {
180→        const subscription = await db.subscription.findUnique({ where: { shop } });
181→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
182→          return { error: "AI recommender requires Growth plan or higher", intent };
183→        }
184→        const fitPreference = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
185→        const betweenSizes = (formData.get("betweenSizes") as string) || "larger";
186→        const rules = JSON.stringify({ fitPreference, betweenSizes });
187→        await db.recommenderConfig.upsert({
188→          where: { shop },
189→          update: { sizingRules: rules },
190→          create: { shop, sizingRules: rules },
191→        });
192→        return { ok: true, intent, message: "Sizing rules saved" };
193→      }
194→
195→      case "test-recommendation": {
196→        const subscription = await db.subscription.findUnique({ where: { shop } });
197→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
198→          return { error: "AI recommender requires Growth plan or higher", intent };
199→        }
200→
201→        const heightCm = parseFloat(formData.get("height") as string);
202→        const weightKg = parseFloat(formData.get("weight") as string);
203→        const bodyType = (formData.get("bodyType") as string) || "regular";
204→        const fitPref = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
205→
206→        if (isNaN(heightCm) || isNaN(weightKg) || heightCm < 100 || heightCm > 250 || weightKg < 30 || weightKg > 250) {
207→          return { error: "Please enter valid height (100–250 cm) and weight (30–250 kg)", intent };
208→        }
209→
210→        // Statistical body proportion model (basic algorithm)
211→        const bmi = weightKg / ((heightCm / 100) ** 2);
212→
213→        const bodyTypeMultipliers: Record<string, { bust: number; waist: number; hips: number }> = {
214→          slim:    { bust: 0.52, waist: 0.43, hips: 0.54 },
215→          regular: { bust: 0.54, waist: 0.46, hips: 0.57 },
216→          athletic:{ bust: 0.56, waist: 0.44, hips: 0.56 },
217→          plus:    { bust: 0.59, waist: 0.52, hips: 0.62 },
218→          petite:  { bust: 0.52, waist: 0.44, hips: 0.55 },
219→        };
220→
221→        const fitBias: Record<string, number> = {
222→          "tight": -2,
223→          "true-to-size": 0,
224→          "relaxed": 2,
225→          "oversized": 4,
226→        };
227→
228→        const mult = bodyTypeMultipliers[bodyType] ?? bodyTypeMultipliers.regular;
229→        const bias = fitBias[fitPref] ?? 0;
230→
231→        const bust = Math.round(heightCm * mult.bust + bias);
232→        const waist = Math.round(heightCm * mult.waist + (bmi - 22) * 0.5 + bias);
233→        const hips = Math.round(heightCm * mult.hips + bias);
234→
235→        // Size chart lookup (bust-based for tops/general)
236→        const sizes = [
237→          { label: "XS", bustMin: 76, bustMax: 83 },
238→          { label: "S",  bustMin: 84, bustMax: 91 },
239→          { label: "M",  bustMin: 92, bustMax: 99 },
240→          { label: "L",  bustMin: 100, bustMax: 107 },
241→          { label: "XL", bustMin: 108, bustMax: 115 },
242→          { label: "2XL",bustMin: 116, bustMax: 123 },
243→          { label: "3XL",bustMin: 124, bustMax: 131 },
244→        ];
245→
246→        const matched = sizes.find((s) => bust >= s.bustMin && bust <= s.bustMax);
247→        const matchedIdx = matched ? sizes.indexOf(matched) : 2;
248→        const size = matched?.label ?? "M";
249→        const confidence = matched
250→          ? Math.round(90 - Math.abs(bust - (matched.bustMin + matched.bustMax) / 2) * 0.8)
251→          : 65;
252→
253→        const alternatives: string[] = [];
254→        if (matchedIdx > 0) alternatives.push(sizes[matchedIdx - 1].label);
255→        if (matchedIdx < sizes.length - 1) alternatives.push(sizes[matchedIdx + 1].label);
256→
257→        return {
258→          ok: true,
259→          intent,
260→          testResult: { size, confidence, alternatives, bust, waist, hips } as TestResult,
261→          message: `Recommended size: ${size}`,
262→        };
263→      }
264→
265→      default:
266→        return { error: "Unknown action", intent };
267→    }
268→  } catch (error) {
269→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
270→    return { error: message, intent };
271→  }
272→};
