 45→// ---------------------------------------------------------------------------
 46→// Loader
 47→// ---------------------------------------------------------------------------
 48→
 49→export const loader = async ({ request }: LoaderFunctionArgs) => {
 50→  const { session } = await authenticate.admin(request);
 51→  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });
 52→
 53→  return {
 54→    config: config ?? {
 55→      displayMode: "popup",
 56→      position: "bottom-right",
 57→      triggerType: "button",
 58→      primaryColor: "#000000",
 59→      successColor: "#16a34a",
 60→      errorColor: "#dc2626",
 61→      backgroundColor: "#ffffff",
 62→      textColor: "#111111",
 63→      borderRadius: "8",
 64→      heading: "Size Guide",
 65→      placeholder: "Select your size",
 66→      buttonText: "Find My Size",
 67→      successMessage: "This size should fit you well!",
 68→      errorMessage: "We couldn't determine your size. Please refer to the chart.",
 69→      showRecommender: true,
 70→      customCss: "",
 71→    },
 72→  };
 73→};
 74→
 75→// ---------------------------------------------------------------------------
 76→// Action
 77→// ---------------------------------------------------------------------------
 78→
 79→export const action = async ({ request }: ActionFunctionArgs) => {
 80→  const { session } = await authenticate.admin(request);
 81→  const formData = await request.formData();
 82→
 83→  try {
 84→    const data = {
 85→      displayMode: (formData.get("displayMode") as string) || "popup",
 86→      position: (formData.get("position") as string) || "bottom-right",
 87→      triggerType: (formData.get("triggerType") as string) || "button",
 88→      primaryColor: (formData.get("primaryColor") as string) || "#000000",
 89→      successColor: (formData.get("successColor") as string) || "#16a34a",
 90→      errorColor: (formData.get("errorColor") as string) || "#dc2626",
 91→      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
 92→      textColor: (formData.get("textColor") as string) || "#111111",
 93→      borderRadius: (formData.get("borderRadius") as string) || "8",
 94→      heading: (formData.get("heading") as string) || "Size Guide",
 95→      placeholder: (formData.get("placeholder") as string) || "Select your size",
 96→      buttonText: (formData.get("buttonText") as string) || "Find My Size",
 97→      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
 98→      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
 99→      showRecommender: formData.get("showRecommender") === "true",
100→      customCss: (formData.get("customCss") as string) || "",
101→    };
102→
103→    await db.widgetConfig.upsert({
104→      where: { shop: session.shop },
105→      update: data,
106→      create: { shop: session.shop, ...data },
107→    });
108→    return { ok: true, message: "Widget settings saved" };
109→  } catch (error) {
110→    return {
111→      error: error instanceof Error ? error.message : "An unexpected error occurred",
112→    };
113→  }
114→};
