  1→import { useState } from "react";
  2→import type { LoaderFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher, useNavigate } from "react-router";
  4→import {
  5→  Page,
  6→  Layout,
  7→  Card,
  8→  BlockStack,
  9→  InlineStack,
 10→  Text,
 11→  Badge,
 12→  Button,
 13→  ButtonGroup,
 14→  Banner,
 15→  InlineGrid,
 16→} from "@shopify/polaris";
 17→import { authenticate } from "../shopify.server";
 18→import db from "../db.server";
 19→import { getPlan, hasFeature } from "../lib/plans";
 20→
 21→// ---------------------------------------------------------------------------
 22→// Types
 23→// ---------------------------------------------------------------------------
 24→
 25→interface DailyDataPoint {
 26→  label: string;
 27→  value: number;
 28→}
 29→
 30→interface TopChart {
 31→  chartId: string | null;
 32→  chartName: string;
 33→  views: number;
 34→  rank: number;
 35→}
 36→
 37→// ---------------------------------------------------------------------------
 38→// Loader
 39→// ---------------------------------------------------------------------------
 40→
 41→export const loader = async ({ request }: LoaderFunctionArgs) => {
 42→  const { session } = await authenticate.admin(request);
 43→  const shop = session.shop;
 44→
 45→  const url = new URL(request.url);
 46→  const fromParam = url.searchParams.get("from");
 47→  const toParam = url.searchParams.get("to");
 48→  const presetParam = url.searchParams.get("preset") ?? "30d";
 49→
 50→  // Resolve date range
 51→  const now = new Date();
 52→  let fromDate: Date;
 53→  let toDate: Date = new Date(now);
 54→  toDate.setHours(23, 59, 59, 999);
 55→
 56→  if (fromParam && toParam) {
 57→    fromDate = new Date(fromParam);
 58→    fromDate.setHours(0, 0, 0, 0);
 59→    const parsedTo = new Date(toParam);
 60→    parsedTo.setHours(23, 59, 59, 999);
 61→    toDate = parsedTo;
 62→  } else {
 63→    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
 64→    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
 65→    fromDate.setHours(0, 0, 0, 0);
 66→  }
 67→
 68→  const dateFilter = { gte: fromDate, lte: toDate };
 69→
 70→  const subscription = await db.subscription.findUnique({ where: { shop } });
 71→  const plan = getPlan(subscription?.planId ?? "free");
 72→  const canViewAnalytics = hasFeature(plan.id, "analytics");
 73→
 74→  if (!canViewAnalytics) {
 75→    return {
 76→      plan,
 77→      canViewAnalytics: false as const,
 78→      stats: null,
 79→      topChartsWithNames: [] as TopChart[],
 80→      dailyTrend: [] as DailyDataPoint[],
 81→      preset: presetParam,
 82→      fromDate: fromDate.toISOString().split("T")[0],
 83→      toDate: toDate.toISOString().split("T")[0],
 84→    };
 85→  }
 86→
 87→  const [
 88→    totalViews,
 89→    totalClicks,
 90→    totalRecommendations,
 91→    totalConverts,
 92→    topCharts,
 93→    rawEvents,
 94→  ] = await Promise.all([
 95→    db.analyticsEvent.count({ where: { shop, eventType: "view", createdAt: dateFilter } }),
 96→    db.analyticsEvent.count({ where: { shop, eventType: "click", createdAt: dateFilter } }),
 97→    db.analyticsEvent.count({ where: { shop, eventType: "recommend", createdAt: dateFilter } }),
 98→    db.analyticsEvent.count({ where: { shop, eventType: "convert", createdAt: dateFilter } }),
 99→    db.analyticsEvent.groupBy({
100→      by: ["sizeChartId"],
101→      where: { shop, eventType: "view", sizeChartId: { not: null }, createdAt: dateFilter },
102→      _count: { id: true },
103→      orderBy: { _count: { id: "desc" } },
104→      take: 5,
105→    }),
106→    db.analyticsEvent.findMany({
107→      where: { shop, eventType: "view", createdAt: dateFilter },
108→      select: { createdAt: true },
109→      orderBy: { createdAt: "asc" },
110→    }),
111→  ]);
112→
113→  // Build daily trend bucketed by day
114→  const dayBuckets: Record<string, number> = {};
115→  const diffMs = toDate.getTime() - fromDate.getTime();
116→  const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
117→  for (let i = 0; i < Math.min(diffDays, 90); i++) {
118→    const d = new Date(fromDate.getTime() + i * 24 * 60 * 60 * 1000);
119→    const key = d.toISOString().split("T")[0];
120→    dayBuckets[key] = 0;
121→  }
122→  for (const ev of rawEvents) {
123→    const key = ev.createdAt.toISOString().split("T")[0];
124→    if (key in dayBuckets) dayBuckets[key]++;
125→  }
126→
127→  // Condense to max 30 bars for readability
128→  const bucketEntries = Object.entries(dayBuckets);
129→  const maxBars = 30;
130→  let dailyTrend: DailyDataPoint[];
131→  if (bucketEntries.length <= maxBars) {
132→    dailyTrend = bucketEntries.map(([date, value]) => ({
133→      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
134→      value,
135→    }));
136→  } else {
137→    // Group into weekly buckets
138→    const weekBuckets: Record<string, number> = {};
139→    for (const [date, count] of bucketEntries) {
140→      const d = new Date(date + "T12:00:00Z");
141→      const weekStart = new Date(d);
142→      weekStart.setDate(d.getDate() - d.getDay());
143→      const wk = weekStart.toISOString().split("T")[0];
144→      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + count;
145→    }
146→    dailyTrend = Object.entries(weekBuckets).map(([date, value]) => ({
147→      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
148→      value,
149→    }));
150→  }
151→
152→  // Resolve chart names
153→  const chartIds = topCharts.map((tc) => tc.sizeChartId).filter((id): id is string => id !== null);
154→  const charts = chartIds.length > 0
155→    ? await db.sizeChart.findMany({ where: { id: { in: chartIds }, shop }, select: { id: true, name: true } })
156→    : [];
157→
158→  const topChartsWithNames: TopChart[] = topCharts.map((tc, idx) => ({
159→    chartId: tc.sizeChartId,
160→    chartName: charts.find((c) => c.id === tc.sizeChartId)?.name ?? "Unknown",
161→    views: tc._count.id,
162→    rank: idx + 1,
163→  }));
164→
165→  // Funnel rates
166→  const clickRate = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(1) : "0";
167→  const recommendRate = totalClicks > 0 ? ((totalRecommendations / totalClicks) * 100).toFixed(1) : "0";
168→  const convertRate = totalRecommendations > 0 ? ((totalConverts / totalRecommendations) * 100).toFixed(1) : "0";
169→  const overallConvertRate = totalViews > 0 ? ((totalConverts / totalViews) * 100).toFixed(1) : "0";
170→
171→  return {
172→    plan,
173→    canViewAnalytics: true as const,
174→    stats: {
175→      totalViews,
176→      totalClicks,
177→      totalRecommendations,
178→      totalConverts,
179→      clickRate,
180→      recommendRate,
181→      convertRate,
182→      overallConvertRate,
183→    },
184→    topChartsWithNames,
185→    dailyTrend,
186→    preset: presetParam,
187→    fromDate: fromDate.toISOString().split("T")[0],
188→    toDate: toDate.toISOString().split("T")[0],
189→  };
190→};
